<?php
 namespace Pterodactyl\Services\Dezerx\Allocations; use Pterodactyl\Models\Node; use Pterodactyl\Models\Allocation; use Pterodactyl\Services\Dezerx\Settings; use Pterodactyl\Exceptions\DisplayException; use Illuminate\Database\Eloquent\Builder; class AllocationFolders { public const KEY = 'allocation-folders'; public const ALL = 'all'; public const IP = 'ip:'; public const FRESH = '__new'; private const ROOM = 60000; private const RUN = 100000; public const ICONS = [ 'fa-folder-o', 'fa-folder-open-o', 'fa-cube', 'fa-th-large', 'fa-gamepad', 'fa-server', 'fa-rocket', 'fa-fire', 'fa-leaf', 'fa-tree', 'fa-shield', 'fa-crosshairs', 'fa-car', 'fa-paw', 'fa-flag', 'fa-flag-checkered', 'fa-bug', 'fa-cogs', 'fa-cog', 'fa-code', 'fa-terminal', 'fa-globe', 'fa-database', 'fa-comments', 'fa-microphone', 'fa-volume-up', 'fa-star', 'fa-lock', 'fa-bolt', 'fa-flask', 'fa-life-ring', 'fa-industry', 'fa-random', 'fa-cloud', 'fa-medkit', 'fa-gavel', 'fa-tint', 'fa-fighter-jet', 'fa-taxi', 'fa-hourglass-half', 'fa-archive', ]; public const COLORS = [ '', '#4c9a2a', '#2f855a', '#2c7a7b', '#3aa8c1', '#2b6cb0', '#4a6fa5', '#5865f2', '#6b46c1', '#7b5cd6', '#8b1e3f', '#c0392b', '#d97706', '#f0a020', '#c9a227', '#8a5a2b', '#6b7d3a', '#4a5568', ]; private static ?array $resolved = null; private static ?array $palette = null; private static ?array $marks = null; public static function colors(): array { return self::$palette ??= self::widen(self::COLORS, 'color'); } public static function icons(): array { return self::$marks ??= self::widen(self::ICONS, 'icon'); } private static function widen(array $offered, string $field): array { foreach (PortCatalogue::profiles() as $profile) { $offered[] = $profile[$field]; } return array_values(array_unique($offered)); } public static function all(): array { if (self::$resolved !== null) { return self::$resolved; } $stored = Settings::get(self::KEY) ?? []; $nodes = []; foreach ((array) ($stored['nodes'] ?? []) as $node => $saved) { $nodes[(string) (int) $node] = self::clean((array) $saved); } return self::$resolved = [ 'enabled' => (bool) ($stored['enabled'] ?? false), 'nodes' => $nodes, ]; } public static function enabled(): bool { return self::all()['enabled']; } public static function setEnabled(bool $on): void { $current = self::all(); Settings::put(self::KEY, [...$current, 'enabled' => $on]); self::$resolved = null; } public static function node(int $node): array { return self::all()['nodes'][(string) $node] ?? ['folders' => [], 'names' => [], 'meta' => []]; } public static function filed(int $node): array { $ids = []; foreach (self::node($node)['folders'] as $folder) { $ids = [...$ids, ...$folder['allocations']]; } return array_values(array_unique($ids)); } public static function listing(Node $node): array { $saved = self::node($node->id); $filed = self::live($node->id, self::filed($node->id)); $perIp = Allocation::query() ->where('node_id', $node->id) ->when($filed !== [], fn (Builder $query) => $query->whereNotIn('id', $filed)) ->selectRaw('ip, COUNT(*) as total, SUM(CASE WHEN server_id IS NULL THEN 1 ELSE 0 END) as free') ->groupBy('ip') ->orderByRaw('INET_ATON(ip) ASC') ->get(); $freeFiled = $filed === [] ? [] : array_flip( Allocation::query() ->where('node_id', $node->id) ->whereIn('id', $filed) ->whereNull('server_id') ->pluck('id') ->map(fn ($id) => (int) $id) ->all(), ); $folders = []; foreach ($saved['folders'] as $folder) { $ids = array_intersect($folder['allocations'], $filed); $folders[] = self::dress([ 'key' => $folder['id'], 'name' => $folder['name'], 'hint' => '', 'count' => count($ids), 'free' => count(array_intersect_key($freeFiled, array_flip($ids))), 'custom' => true, 'dressed' => true, ], $saved, $folder['id']); } foreach ($perIp as $row) { $key = self::IP . $row->ip; $folders[] = self::dress([ 'key' => $key, 'name' => (string) ($saved['names'][$row->ip] ?? $row->ip), 'hint' => $row->ip, 'count' => (int) $row->total, 'free' => (int) $row->free, 'custom' => false, 'dressed' => isset($saved['names'][$row->ip]) || isset($saved['meta'][$key]), ], $saved, $key); } return $folders; } public static function meta(int $node, string $key): array { $saved = self::node($node); return self::wear($saved['meta'][$key] ?? [], $key); } private static function dress(array $folder, array $saved, string $key): array { return [...$folder, ...self::wear($saved['meta'][$key] ?? [], $key)]; } private static function wear(array $meta, string $key): array { return [ 'icon' => (string) ($meta['icon'] ?? '') ?: (str_starts_with($key, self::IP) ? 'fa-server' : 'fa-folder-o'), 'color' => (string) ($meta['color'] ?? ''), 'image' => (string) ($meta['image'] ?? ''), 'note' => (string) ($meta['note'] ?? ''), 'profile' => (string) ($meta['profile'] ?? ''), ]; } public static function label(int $node, string $key): ?string { if ($key === self::ALL) { return null; } $saved = self::node($node); if (str_starts_with($key, self::IP)) { $ip = substr($key, strlen(self::IP)); return (string) ($saved['names'][$ip] ?? $ip); } foreach ($saved['folders'] as $folder) { if ($folder['id'] === $key) { return $folder['name']; } } return null; } public static function narrow(Builder $query, int $node, string $key): Builder { if ($key === self::ALL) { return $query; } if (str_starts_with($key, self::IP)) { $filed = self::filed($node); return $query ->where('ip', substr($key, strlen(self::IP))) ->when($filed !== [], fn (Builder $inner) => $inner->whereNotIn('id', $filed)); } foreach (self::node($node)['folders'] as $folder) { if ($folder['id'] === $key) { return $query->whereIn('id', $folder['allocations'] ?: [0]); } } return $query->whereRaw('1 = 0'); } public static function add(int $node, string $name, array $meta = []): string { $saved = self::node($node); $id = 'f' . bin2hex(random_bytes(5)); $saved['folders'][] = [ 'id' => $id, 'name' => self::name($name), 'allocations' => [], ]; if ($meta !== []) { $saved['meta'][$id] = $meta; } self::put($node, $saved); return $id; } public static function ensure(int $node, string $profile): string { $saved = self::node($node); foreach ($saved['folders'] as $folder) { if (($saved['meta'][$folder['id']]['profile'] ?? '') === $profile) { return $folder['id']; } } $dressed = PortCatalogue::folder($profile); foreach ($saved['folders'] as $folder) { if (mb_strtolower($folder['name']) === mb_strtolower($dressed['name'])) { self::setMeta($node, $folder['id'], $dressed); return $folder['id']; } } return self::add($node, $dressed['name'], $dressed); } public static function rename(int $node, string $key, string $name): void { $saved = self::node($node); $name = self::name($name); if (str_starts_with($key, self::IP)) { $ip = substr($key, strlen(self::IP)); if ($name === $ip || $name === '') { unset($saved['names'][$ip]); } else { $saved['names'][$ip] = $name; } self::put($node, $saved); return; } foreach ($saved['folders'] as $index => $folder) { if ($folder['id'] === $key) { $saved['folders'][$index]['name'] = $name; } } self::put($node, $saved); } public static function setMeta(int $node, string $key, array $meta): void { $saved = self::node($node); $current = $saved['meta'][$key] ?? []; $saved['meta'][$key] = [...$current, ...$meta]; self::put($node, $saved); } public static function shift(int $node, string $key, int $by): void { $saved = self::node($node); $keys = array_column($saved['folders'], 'id'); $at = array_search($key, $keys, true); if ($at === false) { return; } $to = max(0, min(count($saved['folders']) - 1, $at + $by)); if ($to === $at) { return; } $moved = array_splice($saved['folders'], $at, 1); array_splice($saved['folders'], $to, 0, $moved); self::put($node, $saved); } public static function remove(int $node, string $key): int { $saved = self::node($node); $held = 0; foreach ($saved['folders'] as $folder) { if ($folder['id'] === $key) { $held = count($folder['allocations']); } } $saved['folders'] = array_values(array_filter( $saved['folders'], fn (array $folder) => $folder['id'] !== $key, )); unset($saved['meta'][$key]); self::put($node, $saved); return $held; } public static function reset(int $node, string $key): void { $saved = self::node($node); unset($saved['meta'][$key]); if (str_starts_with($key, self::IP)) { unset($saved['names'][substr($key, strlen(self::IP))]); } self::put($node, $saved); } public static function move(int $node, string $key, array $allocations): int { $ids = self::owned($node, $allocations); if ($ids === []) { return 0; } $saved = self::node($node); foreach ($saved['folders'] as $index => $folder) { $saved['folders'][$index]['allocations'] = array_values( array_diff($folder['allocations'], $ids), ); } if ($key !== self::ALL && !str_starts_with($key, self::IP)) { foreach ($saved['folders'] as $index => $folder) { if ($folder['id'] === $key) { $saved['folders'][$index]['allocations'] = array_values(array_unique( [...$folder['allocations'], ...$ids], )); } } } self::put($node, $saved); return count($ids); } public static function file(int $node, array $sorted): array { $done = []; foreach ($sorted as $profile => $ids) { $folder = self::ensure($node, $profile); $moved = self::move($node, $folder, $ids); if ($moved > 0) { $done[$profile] = $moved; } } return $done; } private static function put(int $node, array $saved): void { $current = self::all(); $saved = self::clean($saved); $live = self::live($node, self::filedIn($saved)); foreach ($saved['folders'] as $index => $folder) { $saved['folders'][$index]['allocations'] = array_values( array_intersect($folder['allocations'], $live), ); } $current['nodes'][(string) $node] = $saved; $nodes = Node::query()->whereIn('id', array_keys($current['nodes']))->pluck('id')->all(); foreach (array_keys($current['nodes']) as $known) { if (!in_array((int) $known, $nodes, true)) { unset($current['nodes'][$known]); } } Settings::put(self::KEY, self::fit($current)); self::$resolved = null; } private static function fit(array $current): array { foreach ($current['nodes'] as $node => $saved) { foreach ($saved['folders'] as $index => $folder) { $current['nodes'][$node]['folders'][$index]['allocations'] = self::pack($folder['allocations']); } } $size = strlen((string) json_encode($current, JSON_UNESCAPED_SLASHES | JSON_UNESCAPED_UNICODE)); if ($size > self::ROOM) { throw new DisplayException( 'There is no room left to remember this. Allocation folders are kept in a single settings row, ' . 'which holds about 64KB, and what you have filed across every node has reached it. Nothing was ' . 'changed. Empty a folder you no longer need, or delete some of the allocations that are in one, ' . 'and try again.', ); } return $current; } private static function pack(array $ids): array { sort($ids); $packed = []; $from = null; $to = null; foreach ($ids as $id) { if ($from === null) { $from = $to = $id; continue; } if ($id === $to + 1) { $to = $id; continue; } $packed[] = $from === $to ? $from : "{$from}-{$to}"; $from = $to = $id; } if ($from !== null) { $packed[] = $from === $to ? $from : "{$from}-{$to}"; } return $packed; } private static function unpack(array $rows): array { $ids = []; foreach ($rows as $row) { if (is_int($row) || (is_string($row) && ctype_digit($row))) { $ids[] = (int) $row; continue; } if (!is_string($row) || preg_match('/^(\d+)-(\d+)$/', $row, $run) !== 1) { continue; } [$from, $to] = [(int) $run[1], (int) $run[2]]; if ($to < $from || $to - $from > self::RUN) { continue; } for ($id = $from; $id <= $to; $id++) { $ids[] = $id; } } return array_values(array_unique($ids)); } private static function live(int $node, array $ids): array { if ($ids === []) { return []; } return Allocation::query() ->where('node_id', $node) ->whereIn('id', $ids) ->pluck('id') ->map(fn ($id) => (int) $id) ->all(); } private static function clean(array $saved): array { $folders = []; $ids = []; foreach ((array) ($saved['folders'] ?? []) as $folder) { $id = trim((string) ($folder['id'] ?? '')); if ($id === '' || str_starts_with($id, self::IP) || $id === self::ALL || $id === self::FRESH) { continue; } $ids[$id] = true; $folders[] = [ 'id' => $id, 'name' => self::name((string) ($folder['name'] ?? '')), 'allocations' => self::unpack((array) ($folder['allocations'] ?? [])), ]; } $names = []; foreach ((array) ($saved['names'] ?? []) as $ip => $name) { $name = self::name((string) $name); if ($name !== '') { $names[(string) $ip] = $name; } } $meta = []; foreach ((array) ($saved['meta'] ?? []) as $key => $entry) { $key = (string) $key; $entry = (array) $entry; if (!str_starts_with($key, self::IP) && !isset($ids[$key])) { continue; } $icon = (string) ($entry['icon'] ?? ''); $color = (string) ($entry['color'] ?? ''); $note = self::note((string) ($entry['note'] ?? '')); $profile = (string) ($entry['profile'] ?? ''); $kept = array_filter([ 'icon' => in_array($icon, self::icons(), true) ? $icon : '', 'color' => in_array($color, self::colors(), true) ? $color : '', 'image' => self::image((string) ($entry['image'] ?? '')), 'note' => $note, 'profile' => PortCatalogue::profile($profile) === null ? '' : $profile, ], fn (string $value) => $value !== ''); if ($kept !== []) { $meta[$key] = $kept; } } return ['folders' => $folders, 'names' => $names, 'meta' => $meta]; } private static function filedIn(array $saved): array { $ids = []; foreach ($saved['folders'] as $folder) { $ids = [...$ids, ...$folder['allocations']]; } return array_values(array_unique($ids)); } private static function owned(int $node, array $allocations): array { return self::live($node, array_values(array_unique( array_map('intval', array_filter($allocations, 'is_numeric')), ))); } private static function name(string $name): string { return mb_substr(trim(preg_replace('/\s+/', ' ', strip_tags($name)) ?? ''), 0, 48); } public static function image(string $url): string { $url = trim(strip_tags($url)); if ($url === '' || mb_strlen($url) > 300) { return ''; } return preg_match('#^(https?://[^\s"\'<>]+|/[^\s"\'<>]*)$#i', $url) === 1 ? $url : ''; } private static function note(string $note): string { return mb_substr(trim(preg_replace('/[ \t]+/', ' ', strip_tags($note)) ?? ''), 0, 240); } } 